using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");

// Demonstrate it works by serializing via the typed info
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
//    Use a resolver that only knows about Person — not about int[].
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new PersonOnlyResolver())
};

if (limited.TryGetTypeInfo(typeof(Person), out var info))
    Console.WriteLine($"\n✓ Metadata available for Person (kind={info!.Kind})");
else
    Console.WriteLine("\n✗ No metadata for Person");

if (limited.TryGetTypeInfo(typeof(int[]), out _))
    Console.WriteLine("✓ Metadata available for int[]");
else
    Console.WriteLine("✗ No metadata for int[] — resolver doesn't support it");

// --- Types ---------------------------------------------------------------
record Person(string Name, int Age);

// A resolver that only provides metadata for Person
sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null; // signal "not supported"
    }
}

